INSERT INTO "reports" ("id", "data", "created_at") VALUES ('50ac0f3f-f649-4454-a32d-7b4786e360f9', '"{""ads"": [{""ad_id"": ""120219372003580528""', ' ""angle"": """"', ' ""brand"": ""[\""Equip\""]""', ' ""ad_name"": ""Sept2024', 'camp:retargeting', 'f:Video-UGC', 'conc:recipes', 'hk:indulgent-caramel', 'gen:Female', 'age:30-50', 'off:None""', ' ""ad_text"": """"', ' ""ad_title"": """"', ' ""comments"": []', ' ""image_url"": ""https://v5.airtableusercontent.com/v3/u/40/40/1746028800000/MrE2hy59l_C5kcqOQHySTg/bHHNNBuT2ejf1n3dSzJyhp8YWL07l5GKIFcHkhB8aitR81j9ilOohV9og6bQddba3swxlb4iUCHQKuyfWvBw1RVEQ6QPRyMqja_nMP_9qvi1EcBXj1b03bxBmGq0lo_-EjACDbGy_3MKbu9z-qo1gQ/3Mbr_XLYUVd5UOAE8BoGsrjLcoTQgsd8FcD9PE5N004""', ' ""post_link"": ""https://l.facebook.com/l.php?u=https%3A%2F%2Fwww.equipfoods.com%2Fproducts%2Fprime-protein-beef-isolate-protein&h=AT3qnW-iomdonX1LQrf9jY4GlC0-v3WOWNOgHAAUb609BuxwS_FEJ3M8CUmXqKqB86eDcE9Rup5Z4snFkkMh0GkfYWcl70C82gEuijOqirJprl3X_ezUYEsUfiLS5jnl&s=1""', ' ""video_url"": """"', ' ""angle_type"": ""Feature-Based Angle""', ' ""explanation"": ""The analysis of the ad''s image reveals an emphasis on the product''s features such as ''grass-fed beef isolate''', ' ''natural sweetness from stevia''', ' and ''absence of artificial additives''. According to the Airtable classification guidelines', ' an ad that highlights specific features', ' ingredients', ' or unique product components should be classified as a ''Feature-Based Angle''. The detailed description of the ingredients and their quality signifies a strong focus on these attributes', ' aligning perfectly with this angle classification.""}', ' {""ad_id"": ""120222987573100528""', ' ""angle"": """"', ' ""brand"": ""[\""Equip\""]""', ' ""ad_name"": ""March2025', 'camp:Prospecting', 'f:Video-UGC', 'conc:recipes', 'hk:lets-make-a-gooey-chocolate-brownie', 'gen:Male', 'age:<30', 'off:None', 'creator:Alex-Bolivar""', ' ""ad_text"": ""Fuel your body with the high-quality nutrition it deserves', ' without any a